-- LOCAL PROPOSAL ONLY. Immutable UNPAID Q v2 liabilities, no money movement.
-- Exact reviewed friend-supplied chart cells; not an ACC-mandated payout formula.
begin;
create table app.q_obligation_reviews_v2 (
 id uuid primary key default extensions.gen_random_uuid(),
 tournament_id uuid not null references app.tournaments(id), event_id uuid not null,
 version integer not null check(version between 1 and 256), supersedes_id uuid,
 source_digest text not null check(source_digest ~ '^[a-f0-9]{64}$'),
 source_manifest jsonb not null check(jsonb_typeof(source_manifest)='object'),
 obligations jsonb not null check(jsonb_typeof(obligations)='array'),
 status text not null default 'unpaid' check(status='unpaid'),
 reason text not null check(length(trim(reason)) between 1 and 500 and reason !~ '[[:cntrl:]]'),
 actor_id uuid not null references app.profiles(id), operation_receipt_id uuid not null,
 recorded_at timestamptz not null default clock_timestamp(), unique(event_id,version),unique(id,tournament_id,event_id),
 foreign key(event_id,tournament_id) references app.events(id,tournament_id),
 foreign key(supersedes_id,tournament_id,event_id) references app.q_obligation_reviews_v2(id,tournament_id,event_id),
 foreign key(operation_receipt_id,tournament_id) references app.operation_receipts(id,tournament_id)
);
alter table app.q_obligation_reviews_v2 enable row level security;
alter table app.q_obligation_reviews_v2 force row level security;
revoke all on app.q_obligation_reviews_v2 from public,anon,authenticated,service_role;
create index q_review_v2_tournament_idx on app.q_obligation_reviews_v2(tournament_id);
create index q_review_v2_actor_idx on app.q_obligation_reviews_v2(actor_id);
create index q_review_v2_receipt_idx on app.q_obligation_reviews_v2(operation_receipt_id,tournament_id);
create index q_review_v2_supersedes_idx on app.q_obligation_reviews_v2(supersedes_id,tournament_id,event_id);
create trigger q_review_v2_immutable before update or delete on app.q_obligation_reviews_v2 for each row execute function app.reject_immutable_history();

