-- Calculator receives a server-owned workspace. Public writes never accept these amounts.
create function app.calculate_q_obligations_v2(w jsonb) returns jsonb
language plpgsql immutable set search_path='' as $$
declare p jsonb;pol jsonb;e jsonb;ep jsonb;card jsonb;contributors jsonb;ranked jsonb;rows jsonb;item jsonb;chart jsonb;output jsonb:='[]';
 fund numeric;n integer;i integer;fee bigint;ratio integer;awards jsonb;amount bigint;kind text;code text;
begin
 begin
  if w is null or jsonb_typeof(w)<>'object' or w->'membership' is null or w->'membership'='null'::jsonb
   or w->'membership'->>'supported' is distinct from 'true' or jsonb_array_length(w->'blockers')<>0
   or jsonb_array_length(w->'cards')=0 or jsonb_array_length(w->'membership'->'pools') not between 1 and 2 then raise exception 'source_blocked';end if;
  for p in select value from jsonb_array_elements(w->'membership'->'pools')loop
   select value into pol from jsonb_array_elements(w->'policies')where value->>'poolVersionId'=p->>'poolVersionId';
   if pol is null then raise exception 'policy_required';end if;
   fee:=(p->>'feeMinor')::bigint;contributors:='[]';fund:=0;
   for e in select value from jsonb_array_elements(w->'membership'->'entries')loop
    if (e->>'receivedMinor')::numeric>0 and e->>'allocationCurrent' is distinct from 'true' then raise exception 'funding_unresolved';end if;
    select value into ep from jsonb_array_elements(e->'pools')where value->>'poolVersionId'=p->>'poolVersionId';
    if ep is null then raise exception 'funding_unresolved';end if;
    if ep->>'elected'='true' then
     if ep->>'prePlayElected' is distinct from 'true' or ep->>'paidEntryEligible' is distinct from 'true' or e->>'allocationCurrent' is distinct from 'true'
      or(ep->>'amountAllocatedMinor')::numeric is distinct from fee::numeric
      or coalesce(not starts_with(ep->>'consentReference','Q policy '||(pol->>'id')||': '),true)
      or coalesce(length(trim(substr(ep->>'consentReference',length('Q policy '||(pol->>'id')||': ')+1))),0)=0 then raise exception 'funding_unresolved';end if;
     select value into card from jsonb_array_elements(w->'cards')where value->>'participantId'=e->>'participantId';
     if card is null then raise exception 'source_blocked';end if;
     contributors:=contributors||jsonb_build_array(jsonb_build_object('participantId',e->>'participantId','displayName',e->>'displayName','amountMinor',fee,
      'qualificationRank',card->'qualificationRank','qRank',null,'gamePoints',card->'gamePoints','gamesWon',card->'gamesWon','plusPoints',card->'plusPoints','qualified',card->'qualified'));
     fund:=fund+fee;
    elsif(ep->>'amountAllocatedMinor')::numeric<>0 then raise exception 'funding_unresolved';end if;
   end loop;
   if fund>9007199254740991 then raise exception 'invalid_amount';end if;
   rows:='[]';kind:='award';
   if pol->>'method'='equal-paid-playoff-qualifiers-v2' then
    select coalesce(jsonb_agg(value order by(value->>'qualificationRank')::integer),'[]')into ranked from jsonb_array_elements(contributors)where value->>'qualified'='true';
    n:=jsonb_array_length(ranked);
    if n=0 then
     kind:='refund';for item in select value from jsonb_array_elements(contributors)order by value->>'participantId'loop
      rows:=rows||jsonb_build_array(jsonb_build_object('participantId',item->>'participantId','displayName',item->>'displayName','amountMinor',fee,'qualificationRank',null,'qRank',null));
     end loop;
    else
     i:=0;for item in select value from jsonb_array_elements(ranked)loop
      amount:=floor(fund/n)::bigint+case when i<mod(fund,n)then 1 else 0 end;i:=i+1;
      rows:=rows||jsonb_build_array(jsonb_build_object('participantId',item->>'participantId','displayName',item->>'displayName','amountMinor',amount,'qualificationRank',item->'qualificationRank','qRank',i));
     end loop;
    end if;
   elsif pol->>'method'='graduated-paid-card-rank-v2' then
    -- Monetary tie authority is unresolved: even previously recorded cuts are not silently reused.
    if exists(select 1 from jsonb_array_elements(contributors)a join jsonb_array_elements(contributors)b on a->>'participantId'<b->>'participantId'
      where a->'gamePoints'=b->'gamePoints'and a->'gamesWon'=b->'gamesWon'and a->'plusPoints'=b->'plusPoints')then raise exception 'q_cash_tie_unresolved';end if;
    ratio:=(pol->>'ratio')::integer;n:=jsonb_array_length(contributors);
    select value into chart from jsonb_array_elements(app.q_chart_catalog_v2())where value->>'scheduleId'=pol->>'scheduleId'and(value->>'feeMinor')::bigint=fee and(value->>'ratio')::integer=ratio and(value->>'paidCount')::integer=n;
    if chart is null then raise exception 'chart_review_required';end if;
    awards:=chart->'awardsMinor';
    if jsonb_array_length(awards)<>ceil(n::numeric/ratio)::integer or(select sum(value::text::numeric)from jsonb_array_elements(awards))<>fund then raise exception 'unbalanced_chart';end if;
    select coalesce(jsonb_agg(value order by(value->>'gamePoints')::integer desc,(value->>'gamesWon')::integer desc,(value->>'plusPoints')::integer desc),'[]')into ranked from jsonb_array_elements(contributors);
    i:=0;for item in select value from jsonb_array_elements(ranked)limit jsonb_array_length(awards)loop
     amount:=(awards->>i)::bigint;i:=i+1;
     rows:=rows||jsonb_build_array(jsonb_build_object('participantId',item->>'participantId','displayName',item->>'displayName','amountMinor',amount,'qualificationRank',item->'qualificationRank','qRank',i));
    end loop;
   else raise exception 'policy_required';end if;
   if coalesce((select sum((value->>'amountMinor')::numeric)from jsonb_array_elements(rows)),0)<>fund then raise exception 'unbalanced_chart';end if;
   output:=output||jsonb_build_array(jsonb_build_object('poolVersionId',p->>'poolVersionId','policyId',pol->>'id','name',p->>'name','fundMinor',fund::bigint,'kind',kind,'status','unpaid','rows',rows));
  end loop;
  return jsonb_build_object('obligations',output,'blockers','[]'::jsonb);
 exception when raise_exception or invalid_text_representation or numeric_value_out_of_range or division_by_zero then
  code:=case when sqlerrm in('source_blocked','funding_unresolved','policy_required','q_cash_tie_unresolved','chart_review_required','unbalanced_chart')then sqlerrm else 'invalid_amount'end;
  return jsonb_build_object('obligations',null,'blockers',jsonb_build_array(code));
 end;
end $$;
revoke all on function app.calculate_q_obligations_v2(jsonb)from public,anon,authenticated,service_role;

create function app.q_obligation_sources_v2(actor uuid,tid uuid)returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare w jsonb;c jsonb;manifest jsonb;calc jsonb;blocks jsonb;eid uuid;
begin
 if not exists(select 1 from app.tournament_roles where tournament_id=tid and profile_id=actor and role='director')then return null;end if;
 w:=public.get_q_operating_workspace_v2(actor,tid);if w is null then return null;end if;
 c:=app.q_pool_context_v1(tid);eid:=(c->>'eventId')::uuid;calc:=app.calculate_q_obligations_v2(w);
 blocks:=coalesce(w->'blockers','[]'::jsonb)||coalesce(calc->'blockers','[]'::jsonb);
 if exists(select 1 from app.q_obligation_reviews_v1 where tournament_id=tid and event_id=eid)then blocks:=blocks||'"legacy_review_preserved"'::jsonb;end if;
 manifest:=jsonb_build_object('calculatorVersion','q-unpaid-v2','catalogRevision',app.q_chart_catalog_revision_v2(),'operatingWorkspace',w,'context',c);
 return jsonb_build_object('eventId',eid,'sourceDigest',encode(extensions.digest(convert_to(manifest::text,'utf8'),'sha256'),'hex'),'manifest',manifest,'obligations',case when jsonb_array_length(blocks)=0 then calc->'obligations'else'null'::jsonb end,'blockers',blocks);
end $$;
revoke all on function app.q_obligation_sources_v2(uuid,uuid)from public,anon,authenticated,service_role;

create function app.require_q_review_domain_v2()returns trigger language plpgsql security definer set search_path='' as $$
begin
 perform pg_advisory_xact_lock(hashtextextended('qualification-finalization:'||new.event_id::text,0));
 if tg_table_name='q_obligation_reviews_v2'and exists(select 1 from app.q_obligation_reviews_v1 where event_id=new.event_id)
  or tg_table_name='q_obligation_reviews_v1'and exists(select 1 from app.q_obligation_reviews_v2 where event_id=new.event_id)then raise exception 'q_review_domain_conflict';end if;
 return new;
end $$;
revoke all on function app.require_q_review_domain_v2()from public,anon,authenticated,service_role;
create trigger q_review_v1_domain_v2 before insert on app.q_obligation_reviews_v1 for each row execute function app.require_q_review_domain_v2();
create trigger q_review_v2_domain_v2 before insert on app.q_obligation_reviews_v2 for each row execute function app.require_q_review_domain_v2();

create function public.get_q_obligation_review_workspace_v2(p_actor_id uuid,p_tournament_id uuid)returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare b jsonb;latest app.q_obligation_reviews_v2%rowtype;history jsonb;
begin
 if coalesce(nullif(current_setting('request.jwt.claim.role',true),''),(nullif(current_setting('request.jwt.claims',true),'')::jsonb)->>'role')is distinct from'service_role'then return null;end if;
 b:=app.q_obligation_sources_v2(p_actor_id,p_tournament_id);if b is null then return null;end if;
 select*into latest from app.q_obligation_reviews_v2 where tournament_id=p_tournament_id and event_id=(b->>'eventId')::uuid order by version desc limit 1;
 select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'version',r.version,'supersedesId',r.supersedes_id,'reason',r.reason,'recordedAt',r.recorded_at,'actorId',r.actor_id,'sourceDigest',r.source_digest,'status',r.status,'obligations',r.obligations)order by r.version desc),'[]')into history from app.q_obligation_reviews_v2 r where r.tournament_id=p_tournament_id and r.event_id=(b->>'eventId')::uuid;
 return jsonb_build_object('tournamentId',p_tournament_id,'eventId',b->'eventId','sourceDigest',b->'sourceDigest','preview',b->'obligations','blockers',b->'blockers','currentVersion',coalesce(latest.version,0),'current',latest.id is not null and latest.source_digest=b->>'sourceDigest'and jsonb_array_length(b->'blockers')=0,'history',history,'automaticPayout',false,'canonicalSettlement',false);
end $$;

create function public.record_q_obligation_review_v2(p_actor_id uuid,p_tournament_id uuid,p_request jsonb,p_operation_id uuid)returns jsonb
language plpgsql security definer set search_path='' as $$
declare b jsonb;c jsonb;eid uuid;h text;receipt app.operation_receipts%rowtype;latest app.q_obligation_reviews_v2%rowtype;response jsonb;code text;rid uuid:=extensions.gen_random_uuid();oid uuid:=extensions.gen_random_uuid();
begin
 if coalesce(nullif(current_setting('request.jwt.claim.role',true),''),(nullif(current_setting('request.jwt.claims',true),'')::jsonb)->>'role')is distinct from'service_role'or p_actor_id is null or p_tournament_id is null or p_operation_id is null then return null;end if;
 perform pg_advisory_xact_lock(hashtextextended(p_actor_id::text||':'||p_operation_id::text,0));
 c:=app.q_pool_context_v1(p_tournament_id);eid:=(c->>'eventId')::uuid;if eid is null then return null;end if;
 perform pg_advisory_xact_lock(hashtextextended('qualification-finalization:'||eid::text,0));
 perform 1 from app.tournaments where id=p_tournament_id and status in('open','pending_finalization')for update;if not found then return null;end if;
 perform 1 from app.tournament_roles where tournament_id=p_tournament_id and profile_id=p_actor_id and role='director'for update;if not found then return null;end if;
 perform 1 from app.events where id=eid and tournament_id=p_tournament_id for update;if not found then return null;end if;
 h:=encode(extensions.digest(convert_to(jsonb_build_array('q_obligation_review_v2',p_actor_id,p_tournament_id,p_request)::text,'utf8'),'sha256'),'hex');
 select*into receipt from app.operation_receipts where actor_profile_id=p_actor_id and client_operation_id=p_operation_id;
 if found then if receipt.tournament_id=p_tournament_id and receipt.operation_type='q_obligation_review_v2'and receipt.request_hash=h then return receipt.response_payload;end if;return jsonb_build_object('status','rejected','code','idempotency_conflict');end if;
 begin
  if p_request is null or jsonb_typeof(p_request)<>'object'or(select count(*)from jsonb_object_keys(p_request))<>4 or not(p_request?&array['expectedVersion','sourceDigest','reason','reviewed'])
   or p_request->'reviewed'is distinct from'true'::jsonb or jsonb_typeof(p_request->'expectedVersion')is distinct from'number'or coalesce(p_request->>'expectedVersion','')!~'^(0|[1-9][0-9]*)$'or(p_request->>'expectedVersion')::numeric>255
   or jsonb_typeof(p_request->'sourceDigest')is distinct from'string'or coalesce(p_request->>'sourceDigest','')!~'^[a-f0-9]{64}$'
   or jsonb_typeof(p_request->'reason')is distinct from'string'or length(trim(p_request->>'reason'))not between 1 and 500 or p_request->>'reason'~'[[:cntrl:]]'then raise exception 'invalid_request';end if;
  b:=app.q_obligation_sources_v2(p_actor_id,p_tournament_id);
  if b is null or jsonb_array_length(b->'blockers')<>0 or b->'obligations'='null'::jsonb then raise exception 'source_blocked';end if;
  if b->>'sourceDigest'is distinct from p_request->>'sourceDigest'then raise exception 'source_changed';end if;
  if exists(select 1 from app.event_settlement_finals_v2 where tournament_id=p_tournament_id and event_id=eid)or exists(select 1 from app.standard_singles_settlement_final_versions where tournament_id=p_tournament_id and event_id=eid)then raise exception 'settlement_finalized';end if;
  select*into latest from app.q_obligation_reviews_v2 where event_id=eid order by version desc limit 1;
  if coalesce(latest.version,0)<>(p_request->>'expectedVersion')::integer then raise exception 'stale_version';end if;
  if latest.id is not null and latest.source_digest=b->>'sourceDigest'then raise exception 'already_reviewed';end if;
  response:=jsonb_build_object('status','q_obligations_recorded_v2','reviewId',rid,'eventId',eid,'version',coalesce(latest.version,0)+1,'sourceDigest',b->>'sourceDigest');
  insert into app.operation_receipts(id,tournament_id,actor_profile_id,operation_type,target_id,request_hash,client_operation_id,outcome,response_payload,applied_at)values(oid,p_tournament_id,p_actor_id,'q_obligation_review_v2',eid,h,p_operation_id,'accepted',response,clock_timestamp());
  insert into app.q_obligation_reviews_v2(id,tournament_id,event_id,version,supersedes_id,source_digest,source_manifest,obligations,reason,actor_id,operation_receipt_id)values(rid,p_tournament_id,eid,coalesce(latest.version,0)+1,latest.id,b->>'sourceDigest',b->'manifest',b->'obligations',trim(p_request->>'reason'),p_actor_id,oid);
  insert into app.audit_events(tournament_id,actor_profile_id,operation_receipt_id,entity_type,entity_id,action,after_state)values(p_tournament_id,p_actor_id,oid,'q_obligation_review_v2',rid,'q_obligations_v2_recorded_unpaid',response);return response;
 exception when raise_exception or invalid_text_representation or numeric_value_out_of_range then
  code:=case when sqlerrm in('source_blocked','source_changed','stale_version','already_reviewed','q_review_domain_conflict','settlement_finalized')then sqlerrm else'invalid_request'end;
  response:=jsonb_build_object('status','rejected','code',code);
  insert into app.operation_receipts(tournament_id,actor_profile_id,operation_type,target_id,request_hash,client_operation_id,outcome,response_payload)values(p_tournament_id,p_actor_id,'q_obligation_review_v2',eid,h,p_operation_id,'rejected',response);return response;
 end;
end $$;

create function public.get_q_obligation_review_reconciliation_v2(p_actor_id uuid,p_tournament_id uuid,p_operation_id uuid,p_request jsonb)returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare r app.operation_receipts%rowtype;h text;
begin
 if coalesce(nullif(current_setting('request.jwt.claim.role',true),''),(nullif(current_setting('request.jwt.claims',true),'')::jsonb)->>'role')is distinct from'service_role'or not exists(select 1 from app.tournament_roles where tournament_id=p_tournament_id and profile_id=p_actor_id and role='director')then return null;end if;
 h:=encode(extensions.digest(convert_to(jsonb_build_array('q_obligation_review_v2',p_actor_id,p_tournament_id,p_request)::text,'utf8'),'sha256'),'hex');
 select*into r from app.operation_receipts where actor_profile_id=p_actor_id and client_operation_id=p_operation_id;
 if found and(r.tournament_id<>p_tournament_id or r.operation_type<>'q_obligation_review_v2'or r.request_hash<>h)then return jsonb_build_object('authorized',true,'result',jsonb_build_object('status','rejected','code','idempotency_conflict'));end if;
 return jsonb_build_object('authorized',true,'result',r.response_payload);
end $$;
revoke all on function public.get_q_obligation_review_workspace_v2(uuid,uuid),public.record_q_obligation_review_v2(uuid,uuid,jsonb,uuid),public.get_q_obligation_review_reconciliation_v2(uuid,uuid,uuid,jsonb)from public,anon,authenticated;
grant execute on function public.get_q_obligation_review_workspace_v2(uuid,uuid),public.record_q_obligation_review_v2(uuid,uuid,jsonb,uuid),public.get_q_obligation_review_reconciliation_v2(uuid,uuid,uuid,jsonb)to service_role;
commit;
